/**
 * @file ndviLayer.js
 * @description Manages rendering and opacity of dynamic XYZ raster tile overlays
 * generated by Google Earth Engine for Sentinel-2 NDVI canopy visualization over MapLibre GL JS.
 * Ensures the primary map canvas ONLY ever renders the NDVI Heatmap overlay, preserving the
 * crisp sub-meter Esri satellite basemap underneath.
 */

export class NdviLayerManager {
  /**
   * @param {Object} map - Active MapLibre map instance
   */
  constructor(map) {
    this.map = map;
    this.sourceId = "sentinel2-source";
    this.layerId = "sentinel2-layer";
    this.legacySourceId = "ndvi-source";
    this.legacyLayerId = "ndvi-layer";
    this.defaultOpacity = 0.75;
    this.currentOpacity = 0.75;

    this.ndviTileUrl = null;
  }

  /**
   * Mounts or updates the dynamic NDVI raster tile layer onto the map underneath vector labels.
   * @param {string} tileUrlTemplate - Google Earth Engine NDVI XYZ URL template
   * @param {number} [opacity=0.75] - Layer opacity between 0.0 and 1.0
   */
  setNdviLayer(tileUrlTemplate, opacity = this.defaultOpacity) {
    this.ndviTileUrl = tileUrlTemplate || null;
    this.currentOpacity = typeof opacity === "number" ? Math.max(0.0, Math.min(1.0, opacity)) : this.defaultOpacity;

    this.mountNdviLayer();
  }

  /**
   * Backward-compatible setter for setting layer URLs (strictly mounts NDVI on the map).
   * @param {Object} params
   * @param {string} params.ndviTileUrl - Google Earth Engine NDVI XYZ URL template
   * @param {number} [params.opacity=0.75] - Initial opacity (0.0 to 1.0)
   */
  setLayerUrls({ ndviTileUrl, opacity = this.defaultOpacity }) {
    this.setNdviLayer(ndviTileUrl, opacity);
  }

  /**
   * Mounts the NDVI raster tile layer on the map canvas beneath administrative labels and borders.
   */
  mountNdviLayer() {
    if (!this.map) return;

    if (!this.ndviTileUrl) {
      this.removeCurrentLayer();
      return;
    }

    this.removeCurrentLayer();

    try {
      this.map.addSource(this.sourceId, {
        type: "raster",
        tiles: [this.ndviTileUrl],
        tileSize: 256,
        attribution: "Sentinel-2 &copy; ESA / Google Earth Engine"
      });

      // Find the best layer to insert underneath (keep political boundaries and labels on top)
      let beforeLayerId = undefined;
      const layersToPrecede = [
        "boundary-country",
        "place-city-label",
        "place-city-shield",
        "boundary-state",
        "gl-draw-polygon-fill-inactive.cold",
        "gl-draw-polygon-fill-active.cold"
      ];

      for (const id of layersToPrecede) {
        if (this.map.getLayer(id)) {
          beforeLayerId = id;
          break;
        }
      }

      this.map.addLayer(
        {
          id: this.layerId,
          type: "raster",
          source: this.sourceId,
          paint: {
            "raster-opacity": this.currentOpacity
          }
        },
        beforeLayerId
      );
    } catch (err) {
      console.error("Failed to mount Sentinel-2 NDVI raster layer:", err);
    }
  }

  /**
   * Updates opacity of the currently mounted raster layer.
   * @param {number} opacity - Opacity value between 0.0 and 1.0
   */
  setOpacity(opacity) {
    this.currentOpacity = Math.max(0.0, Math.min(1.0, opacity));
    if (this.map && this.map.getLayer(this.layerId)) {
      this.map.setPaintProperty(this.layerId, "raster-opacity", this.currentOpacity);
    }
  }

  /**
   * Checks if NDVI layer is currently mounted on the map.
   * @returns {boolean}
   */
  isMounted() {
    return Boolean(this.map && this.map.getLayer(this.layerId));
  }

  /**
   * Removes active Sentinel-2 tile layer and any legacy layers from map.
   */
  removeCurrentLayer() {
    if (!this.map) return;
    try {
      if (this.map.getLayer(this.layerId)) {
        this.map.removeLayer(this.layerId);
      }
      if (this.map.getSource(this.sourceId)) {
        this.map.removeSource(this.sourceId);
      }
      // Also clean legacy IDs if any exist
      if (this.map.getLayer(this.legacyLayerId)) {
        this.map.removeLayer(this.legacyLayerId);
      }
      if (this.map.getSource(this.legacySourceId)) {
        this.map.removeSource(this.legacySourceId);
      }
    } catch (err) {
      console.warn("Error removing Sentinel-2 layer:", err);
    }
  }
}
